import{z as r,x as l,o as e,c as d,q as B,j as o,D as t,d as A,s as i,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"抽象数据类型","description":"","frontmatter":{"title":"抽象数据类型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/adt-cost.md","filePath":"cs/adt-cost.md","lastUpdated":1791063341000}'),p={name:"cs/adt-cost.md"};function D(m,a,c,h,T,u){const s=l("Mermaid");return e(),d("div",null,[a[2]||(a[2]=B('<h1 id="抽象数据类型" tabindex="-1">抽象数据类型 <a class="header-anchor" href="#抽象数据类型" aria-label="Permalink to &quot;抽象数据类型&quot;">​</a></h1><div class="epigraph"><p>先约定对象上允许哪些操作以及它们的代价，再选一种比特布局去实现；布局可换，合同不能偷换。</p><footer>—— 据 Liskov and Zilles, Programming with Abstract Data Types, SIGPLAN 1974；Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms 整理</footer></div><p><a href="/cs/cache-side-channel">上一课</a>把微结构进阶收到 Prime+Probe：组相联的占用能当信道，性能机制即安全边界，不能单靠 ISA 正确性。本课不重讲 MESI，也不从「计算机是什么」另起。缺口是：还没有给<strong>可复用的布局</strong>命名——栈、表、图在 ISA 里都只是 load/store。<a href="/cs/bit-as-distinction">比特作为区分</a>给出串，<a href="/cs/asymptotic-notation">渐近记号</a>给出步数怎么写。本课只钉抽象数据类型：操作集合加代价，实现另选。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>体系结构课结束时，程序员仍每次用手排寄存器和地址。同一套「后进先出」可以是数组顶指针，也可以是链表，调用约定已经用过其中一种，却没有把它写成可替换的合同。缺口不是新的特权级，而是把对象从具体指令里抽出来：<strong>构造、插入、查找、删除各允许做什么，最坏或摊还各多少步</strong>。</p><p>没有这层，后课无法比较数组与链表：它们会混成「都是一串元素」。代价必须进合同，否则局部性与 \\(O(1)\\) 下标会被说成同一件事。</p><p><span class="marginnote">ADT 不是 OOP 课。Liskov 强调的是接口与表示分离；本栏用它连接 ISA 与 CLRS 里的结构。</span></p><p><span class="marginnote">术语翻译：ADT 就是用「只写允许哪些操作、各花多少步，不写内存里怎么摆」的手段，来做「换掉实现而不改调用代码」的事。合同里连代价都写明，是为了防止有人换个实现后把 \\(O(1)\\) 悄悄换成 \\(O(n)\\) 还叫同一个名字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>指定一个对象类型 \\(T\\) 和有限个操作，每个操作给出前置条件与渐近代价（最坏、平均或摊还，须声明）。正确性相对抽象状态（序列、集合、全序映射），不相对某次 <code>sw</code> 的地址。同一 \\(T\\) 可以有多种表示，后课逐个给。</p>',10)),(e(),o(n,null,{default:t(()=>[i(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISA%5B%22%E6%8C%87%E4%BB%A4%E5%B7%B2%E8%83%BD%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20ADT%5B%22%E6%93%8D%E4%BD%9C%20%2B%20%E4%BB%A3%E4%BB%B7%E5%90%88%E5%90%8C%22%5D%0A%20%20ADT%20--%3E%20ARR%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%95%B0%E7%BB%84%E8%A1%A8%E7%A4%BA%22%5D%0A%20%20ADT%20--%3E%20LIST%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%93%BE%E8%A1%A8%E8%A1%A8%E7%A4%BA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"本课不引入任何一种具体结构的不变式细节。只要求：换表示不得偷偷改合同——若查找从 \\(O(1)\\) 变成 \\(O(n)\\)，那是另一种 ADT 或另一种实现承诺。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[A("有了合同，"),E("a",{href:"/cs/locality-principle"},"局部性原理"),A("变成实现层的注释：同一「取第 \\(i\\) 个」在数组上吃空间局部性，在链表上可能每次 cache 缺失。渐近记号数的是步，步的常数含命中与缺失；后课会把两者拆开写，但合同先写步数。")],-1)),a[6]||(a[6]=E("p",null,"NUMA 上远程节点是又一层常数。ADT 课默认分析单处理器 RAM 模型，需要时再加一句「布局破坏局部性则常数爆炸」，不把每课重写成体系结构。后课的每一种结构，都先写合同再写一种表示，不从晶体管另起。",-1)),a[7]||(a[7]=E("p",null,"方法一节的图回答「合同从哪里来、通向哪些表示」，下面这张回答另一个问题：同一个调用「查找第 \\(i\\) 个」，穿过两种表示时代价分别怎么兑现。",-1)),(e(),o(n,null,{default:t(()=>[i(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E8%B0%83%E7%94%A8%E6%96%B9%3A%20%E6%9F%A5%E7%AC%AC%20i%20%E4%B8%AA%22%5D%20--%3E%20K%7B%22%E5%90%88%E5%90%8C%E6%89%BF%E8%AF%BA%E7%9A%84%E4%BB%A3%E4%BB%B7%22%7D%0A%20%20K%20--%3E%20A%5B%22%E8%A1%A8%E7%A4%BA%E4%B8%80%3A%20%E6%95%B0%E7%BB%84%22%5D%0A%20%20K%20--%3E%20B%5B%22%E8%A1%A8%E7%A4%BA%E4%BA%8C%3A%20%E9%93%BE%E8%A1%A8%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E5%9F%BA%E5%9C%B0%E5%9D%80%20%2B%20i%20x%20%E6%AD%A5%E9%95%BF%20%E7%9B%B4%E6%8E%A5%E5%AF%BB%E5%9D%80%2C%20O(1)%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E4%BB%8E%E8%A1%A8%E5%A4%B4%E9%80%90%E4%B8%AA%E8%B5%B0%20i%20%E6%AD%A5%2C%20O(n)%22%5D%0A%20%20A1%20--%3E%20D%5B%22%E8%B0%83%E7%94%A8%E6%96%B9%E4%BB%A3%E7%A0%81%E4%B8%8D%E5%8F%98%22%5D%0A%20%20B1%20--%3E%20D%0A%20%20D%20--%3E%20E%7B%22%E5%AE%A3%E7%A7%B0%E7%9A%84%E4%BB%A3%E4%BB%B7%E4%B8%8E%E5%AE%9E%E7%8E%B0%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20E%20--%20%22%E5%90%A6%22%20--%3E%20F%5B%22%E5%90%88%E5%90%8C%E8%A2%AB%E5%81%B7%E6%8D%A2%2C%20%E4%B8%8D%E8%AE%B8%22%5D%0A%20%20E%20--%20%22%E6%98%AF%22%20--%3E%20G%5B%22%E5%90%88%E6%B3%95%E6%9B%BF%E6%8D%A2%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=B('<p><span class="marginnote">直觉类比：合同像墙上的插座标准——电器（算法）不管墙里电线怎么走（表示），只认插座形状和电压电流规格（操作与代价）。只要规格不变，重排墙内布线，电器插上就能用；但把 220 V 换成 110 V 还标着 220 V，就是偷换合同。</span></p><p><span class="marginnote">数字实例：同样是「查找」，数组 \\(O(1)\\) 与链表 \\(O(n)\\) 在 \\(n=10^6\\) 时是「一步」与「一百万步」的差距——这正是为什么合同必须声明代价：调用方要拿它做工程决策，而不只是接口形状。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把类、继承、虚函数请进来。也不把「抽象」写成无代价：没有代价的接口无法在后课做选择。形式化代数规范（ADT 作为等式理论）不在主干。</p><p>后课默认：谈到栈、队列、字典、图，先有操作与代价，再谈表示。第一份表示是数组。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>机器会执行了；本课开始命名操作合同，而不是某次 load 的地址。</li><li>ADT = 操作 + 代价；表示可换，合同不可偷。</li><li>数组随机访问是下一课的第一种表示。</li><li>本课不把类与继承请进来；没有代价的接口无法选择表示。</li><li>出处：Liskov and Zilles, 1974；Cormen et al., <em>Introduction to Algorithms</em>。</li></ul>',7))])}const _=r(p,[["render",D]]);export{C as __pageData,_ as default};
